for a in anchors:
 id,kind,code,title,system,machine,cl,source,fmi,sym,risk=a
 catalog.append({'kind':kind,'code':code,'title':title,'source':source,'note':'Associação ilustrativa de publicação/catálogo indicado. Confirmar efetividade OEM por ECM, modelo, série e software.'})
for code,title,source in [('E360 (3)','Pressão de óleo baixa — gravidade máxima','cat_event'),('E361 (2)','Temperatura do arrefecimento alta — moderada','cat_event'),('E362 (3)','Excesso de rotação — severo','cat_event'),('P119E / SPN 190 FMI 2','Rotação do motor errática em controle DEUTZ MD1','deutz_pdf'),('SPN 614 FMI 14','Posicionamento/carretel de direção: falha especial PVED-CL','danfoss_steer'),('SPN 2661 FMI 4','Joystick JS1 eixo Y: tensão abaixo','danfoss_joy'),('SPN 2660 FMI 14','Joystick JS1 eixo X: verificação especial de redundância','danfoss_joy')]:
 catalog.append({'kind':'Adicional','code':code,'title':title,'source':source,'note':'Referência dependente da plataforma indicada; não generalizar.'})

cases=[]
# Assign campaigns by key and variant sophistication
section_map={'Elétrica':0,'Auxiliares':0,'Hidráulica':1,'Transmissão':2,'Rede CAN':3,'Motor':4,'Arrefecimento':4,'Admissão':5,'Direção':6,'Controle':6}
for ai,a in enumerate(anchors):
 ident,codekind,code,title,system,machine,cl,source,fmi,sym,risk=a
 opts=variants[cl]
 for vi,v in enumerate(opts):
  chapter=section_map[system]
  if vi==2 and ai%5==0:chapter=7
  if cl=='network':chapter=3
  # minor campaign rebalance advanced cases
  case={
   'id':f'CF-{ai+1:02d}-{vi+1}', 'chapter':chapter,'anchor':ident,'scenario':vi+1,'title': f'{title} — {v["tag"]}',
   'system':system,'machine':machine,'code':code,'protocol':codekind,'source':source,'fmi':fmi,'risk':risk,
   'brief':sym,'context':f'Caso de treinamento #{ai+1:02d}.{vi+1}. A indicação eletrônica é verossímil, mas a cronologia e as medições a seguir são simulações didáticas. Não há associação comprovada a uma máquina específica da frota.',
   'root':v['root'],'inspection':v['inspection'],'electrical':v['electrical'],'history':v['history'],'correctRepair':v['repair'],'repairType':v['type'],
   'type':cl, 'difficulty':1+(ai//9)+(vi==2),
   'reward':620+80*(ai//8)+40*vi,'repairPart':('kit_sensor' if cl in ('input','physical','calibrate') else 'kit_atuador' if cl=='output' else 'kit_alvo' if cl=='speed' else 'kit_rede' if cl=='network' else 'kit_ajuste'),
   'threat': 'A condição deve ser tratada como potencialmente grave até confirmação.' if risk=='critica' else 'Confirmar a condição e planejar as medidas seguras antes de retornar à operação.'
  }
  cases.append(case)
assert len(cases)==72
